// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player) public {
        // Ensure the player has not wagered before
        bool hasWageredBefore = c.hasPlayerWagered(player);
        // Adjust bet limit to some value (doesn't matter for the assertion)
        c.AdjustBetAmounts(1234);
        // After AdjustBetAmounts, the wagers mapping should be unaffected, so if the player never wagered, hasPlayerWagered should be false.
        vm.assume(!hasWageredBefore); // Ensure we only test players with zero wager
        assertTrue(!c.hasPlayerWagered(player));
    }
}

